const now = new Date();
const isoDate = now.toISOString().slice(0, 10);
const seedTopics = [
  'La historia completa de la inteligencia artificial',
  'Como cambiaron internet los primeros algoritmos de recomendacion',
  'La carrera espacial contada como una historia de decisiones imposibles',
  'Las tecnologias que parecen modernas pero nacieron hace decadas',
  'Por que los grandes inventos ocurren en momentos concretos de la historia',
  'Errores cientificos famosos que terminaron cambiando el mundo'
];
const topicIndex = Math.floor(now.getTime() / 86400000) % seedTopics.length;
const topic = seedTopics[Math.abs(topicIndex)];
return [{
  json: {
    run: {
      id: `run-${isoDate}`,
      date: isoDate,
      topic,
      status: 'draft'
    },
    config: {
      channelSlug: 'youtube-longform-ai',
      channelName: 'YouTube Longform AI',
      language: 'es',
      timezone: 'Europe/Madrid',
      niche: 'historia, ciencia, tecnologia y curiosidades',
      targetMinutes: 38,
      publishHourLocal: '18:00',
      llm: {
        provider: 'groq',
        model: 'llama-3.3-70b-versatile'
      },
      tts: {
        provider: 'elevenlabs',
        voiceId: 'EXAVITQu4vr4xnSDxMaL'
      },
      visuals: {
        stockProvider: 'pexels',
        scenesPerChapter: 9,
        preferredMix: {
          stockVideo: 0.6,
          aiImage: 0.25,
          textSlide: 0.15
        }
      },
      youtube: {
        privacyStatus: 'private',
        categoryId: '27',
        defaultTags: ['youtube', 'longform', 'documental', 'curiosidades', 'historia', 'ciencia']
      }
    },
    prompts: {
      researchSystem: 'Eres un researcher senior para YouTube longform. Devuelve solo JSON valido.',
      researchUser: `Prepara un research pack para un video de 38 minutos sobre: ${topic}. Devuelve angulo, promesa, audiencia, keywords, hechos, posibles capitulos y puntos de retencion.`,
      outlineSystem: 'Eres un guionista senior de retencion para YouTube. Devuelve solo JSON valido.',
      scriptSystem: 'Eres un guionista de documentales faceless. Devuelve solo JSON valido.'
    },
    integrations: {
      researchLlmEnabled: false,
      outlineLlmEnabled: false,
      scriptLlmEnabled: false,
      ttsEnabled: false,
      renderEnabled: false,
      youtubeUploadEnabled: false
    }
  }
}];

const data = $input.first().json;
const raw = data.body?.choices?.[0]?.message?.content;
let research = null;
if (raw) {
  try {
    research = JSON.parse(raw);
  } catch (error) {
    research = null;
  }
}
if (!research) {
  research = {
    angle: `Explicar ${data.run.topic} como una historia conectada y facil de consumir`,
    promise: 'El espectador entendera el contexto, los momentos clave y por que este tema importa hoy.',
    audience: 'Publico general interesado en videos largos de aprendizaje y curiosidad.',
    keywords: ['contexto', 'historia', 'impacto', 'curiosidades', 'personajes clave'],
    retentionHooks: ['abrir con una promesa fuerte', 'cerrar cada capitulo con una pregunta', 'alternar contexto y consecuencias'],
    facts: [
      'Hay un origen historico claro que sirve de hook.',
      'Existen varios hitos intermedios que permiten dividir el video en capitulos.',
      'El tema conecta con decisiones humanas, errores y cambios culturales.',
      'Se puede explicar con ejemplos concretos y visuales faciles de producir.'
    ],
    chapterIdeas: [
      'Contexto inicial',
      'Primer gran punto de inflexion',
      'Expansion y adopcion',
      'Errores, riesgos o mitos',
      'Consecuencias actuales',
      'Que puede pasar despues'
    ]
  };
}
return [{ json: { ...data, research } }];

const data = $input.first().json;
const raw = data.body?.choices?.[0]?.message?.content;
let outline = null;
if (raw) {
  try {
    outline = JSON.parse(raw);
  } catch (error) {
    outline = null;
  }
}
if (!outline) {
  const chapterTitles = [
    'El origen del problema o de la idea',
    'Los primeros intentos que casi nadie recuerda',
    'El momento que cambio todo',
    'La fase de crecimiento y adopcion',
    'Los errores que generaron nuevas decisiones',
    'Los protagonistas que empujaron el cambio',
    'El impacto en la vida actual',
    'Lo que viene despues y por que importa'
  ];
  outline = {
    workingTitle: data.run.topic,
    hook: `Hoy vas a entender ${data.run.topic} desde el principio hasta sus consecuencias actuales.`,
    cta: 'Si te gustan este tipo de historias largas y bien explicadas, suscribete para el siguiente episodio.',
    chapters: chapterTitles.map((title, index) => ({
      chapterIndex: index + 1,
      title,
      objective: `Mantener retencion mientras se desarrolla ${title.toLowerCase()}`,
      targetMinutes: index === 0 ? 4 : 4.25
    }))
  };
}
return [{ json: { ...data, outline } }];

const data = $input.first().json;
const raw = data.body?.choices?.[0]?.message?.content;
let script = null;
if (raw) {
  try {
    script = JSON.parse(raw);
  } catch (error) {
    script = null;
  }
}
if (!script) {
  const intro = `${data.outline.hook} En este video vamos a recorrer el contexto, los puntos de inflexion y las consecuencias de una forma clara, sin relleno y manteniendo el hilo de la historia.`;
  const chapterScripts = data.outline.chapters.map((chapter) => ({
    chapterIndex: chapter.chapterIndex,
    title: chapter.title,
    narration: `${chapter.title}. En esta parte explicamos el contexto, introducimos a los actores principales, desarrollamos el conflicto o la idea central y cerramos con una transicion que obligue al espectador a quedarse para el siguiente bloque.`
  }));
  const outro = data.outline.cta;
  script = {
    title: `${data.run.topic}: historia completa en 38 minutos`,
    description: `Video largo automatizado sobre ${data.run.topic}. Formato documental, narrado y estructurado por capitulos.`,
    intro,
    chapters: chapterScripts,
    outro
  };
}
return [{ json: { ...data, script } }];

const data = $input.first().json;
const scenes = [];
let sceneIndex = 1;
for (const chapter of data.outline.chapters) {
  for (let i = 0; i < data.config.visuals.scenesPerChapter; i++) {
    const visualType = i % 5 === 0 ? 'text_slide' : (i % 3 === 0 ? 'ai_image' : 'stock_video');
    scenes.push({
      sceneIndex,
      chapterIndex: chapter.chapterIndex,
      chapterTitle: chapter.title,
      visualType,
      query: `${data.run.topic} ${chapter.title}`,
      narrationBeat: `Escena ${i + 1} del capitulo ${chapter.chapterIndex}: desarrollo visual de ${chapter.title.toLowerCase()}.`,
      targetDurationSeconds: Math.round((chapter.targetMinutes * 60) / data.config.visuals.scenesPerChapter)
    });
    sceneIndex += 1;
  }
}
const assetPlan = scenes.map((scene) => ({
  sceneIndex: scene.sceneIndex,
  provider: scene.visualType === 'stock_video' ? 'pexels' : 'image-generator',
  requestedType: scene.visualType,
  searchText: scene.query
}));
const productionPlan = {
  chapterCount: data.outline.chapters.length,
  sceneCount: scenes.length,
  estimatedDurationMinutes: data.config.targetMinutes,
  renderStrategy: 'external-render-provider-recommended',
  uploadStrategy: 'youtube-api-after-render'
};
return [{ json: { ...data, scenes, assetPlan, productionPlan } }];

const data = $input.first().json;
const title = data.script?.title || `${data.run.topic}: historia completa en ${data.config.targetMinutes} minutos`;
const description = [
  data.script?.description || `Video largo sobre ${data.run.topic}.`,
  '',
  'Estructura prevista:',
  ...data.outline.chapters.map((chapter, index) => `${index + 1}. ${chapter.title}`),
  '',
  'Generado con un workflow de n8n y preparado para integrar research, guion, voz, assets, render y publicacion.'
].join('\n');
const youtubePackage = {
  title,
  description,
  tags: data.config.youtube.defaultTags,
  privacyStatus: data.config.youtube.privacyStatus,
  categoryId: data.config.youtube.categoryId,
  scheduledForLocal: `${data.run.date} ${data.config.publishHourLocal}`
};
const issues = [];
if (!data.outline?.chapters?.length) issues.push('No hay outline');
if (!data.script?.chapters?.length) issues.push('No hay guion por capitulos');
if ((data.scenes || []).length < 40) issues.push('El numero de escenas es demasiado bajo para un longform de 38 minutos');
if (!data.productionPlan) issues.push('Falta el production plan');
const status = issues.length ? 'needs_review' : 'ready_for_integrations';
const nextActions = [
  'Activar nodo de research LLM',
  'Activar nodo de outline LLM',
  'Activar nodo de script LLM',
  'Conectar TTS real por capitulo',
  'Conectar proveedor de render externo',
  'Conectar subida final a YouTube'
];
return [{ json: { ...data, youtubePackage, quality: { issues, status }, nextActions } }];
